-- =============================================================================
-- Migration V14: Bảng điều phối vận chuyển
-- Tables: vehicle_types, vehicles, moving_schedules, schedule_staff_assignments, schedule_vehicle_assignments
-- So với ERD: status varchar + Java enum; staff_id trỏ staff(user_id)
-- =============================================================================
CREATE TABLE IF NOT EXISTS "vehicle_types" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL UNIQUE,
  "description" text,
  "max_load_kg" decimal(10,2),
  "max_volume_m3" decimal(10,2),
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "vehicles" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plate" varchar(30) NOT NULL UNIQUE,
  "vehicle_type_id" int NOT NULL,
  "capacity_m3" decimal(10,2),
  "status" varchar(20) NOT NULL DEFAULT 'AVAILABLE',
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_vehicles_type FOREIGN KEY ("vehicle_type_id") REFERENCES "vehicle_types" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_vehicles_status CHECK (status IN ('AVAILABLE', 'IN_USE', 'MAINTENANCE', 'INACTIVE'))
);
CREATE INDEX IF NOT EXISTS idx_vehicles_type ON "vehicles" ("vehicle_type_id");

CREATE TABLE IF NOT EXISTS "moving_schedules" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "scheduled_start_at" timestamp NOT NULL,
  "scheduled_end_at" timestamp NOT NULL,
  "actual_start_at" timestamp,
  "actual_end_at" timestamp,
  "status" varchar(20) NOT NULL DEFAULT 'PLANNED',
  "note" text,
  "created_by" bigint,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_moving_schedules_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_moving_schedules_created_by FOREIGN KEY ("created_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_moving_schedules_status CHECK (status IN ('PLANNED', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'RESCHEDULED')),
  CONSTRAINT chk_moving_schedules_planned_range CHECK (scheduled_end_at > scheduled_start_at),
  CONSTRAINT chk_moving_schedules_actual_range CHECK (actual_end_at IS NULL OR actual_start_at IS NULL OR actual_end_at >= actual_start_at),
  CONSTRAINT chk_moving_schedules_started CHECK (status NOT IN ('IN_PROGRESS', 'COMPLETED') OR actual_start_at IS NOT NULL),
  CONSTRAINT chk_moving_schedules_completed CHECK (status <> 'COMPLETED' OR actual_end_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_moving_schedules_booking ON "moving_schedules" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_moving_schedules_start_status ON "moving_schedules" ("scheduled_start_at", "status");

CREATE TABLE IF NOT EXISTS "schedule_staff_assignments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "moving_schedule_id" int NOT NULL,
  "staff_id" bigint NOT NULL,
  "role" varchar(20) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'PLANNED',
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ssa_schedule FOREIGN KEY ("moving_schedule_id") REFERENCES "moving_schedules" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_ssa_staff FOREIGN KEY ("staff_id") REFERENCES "staff" ("user_id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_ssa_role CHECK (role IN ('SUPERVISOR', 'MOVER', 'DRIVER')),
  CONSTRAINT chk_ssa_status CHECK (status IN ('PLANNED', 'ASSIGNED', 'CONFIRMED', 'COMPLETED', 'CANCELLED'))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ssa_schedule_staff ON "schedule_staff_assignments" ("moving_schedule_id", "staff_id");
CREATE INDEX IF NOT EXISTS idx_ssa_staff ON "schedule_staff_assignments" ("staff_id");
CREATE UNIQUE INDEX IF NOT EXISTS uq_ssa_one_supervisor ON "schedule_staff_assignments" ("moving_schedule_id")
  WHERE role = 'SUPERVISOR' AND status <> 'CANCELLED';

CREATE TABLE IF NOT EXISTS "schedule_vehicle_assignments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "moving_schedule_id" int NOT NULL,
  "vehicle_id" int NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'PLANNED',
  "note" text,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_sva_schedule FOREIGN KEY ("moving_schedule_id") REFERENCES "moving_schedules" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_sva_vehicle FOREIGN KEY ("vehicle_id") REFERENCES "vehicles" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_sva_status CHECK (status IN ('PLANNED', 'ASSIGNED', 'CONFIRMED', 'COMPLETED', 'CANCELLED'))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sva_schedule_vehicle ON "schedule_vehicle_assignments" ("moving_schedule_id", "vehicle_id");
CREATE INDEX IF NOT EXISTS idx_sva_vehicle ON "schedule_vehicle_assignments" ("vehicle_id");
